/**
 * Shared PURE helpers for the Source-engine family appliers (cs2, cs16, tf2,
 * l4d2, gmod, kf2). No I/O, no node imports: the settings page, the setup-script
 * bake in worker/game-variant.ts and the worker appliers all use these, so a
 * fresh install, a reinstall and a Settings save produce the same server.
 */

export type V = Record<string, string | number | boolean | undefined>;

/** Passwords / tokens that travel unquoted through a shell `eval`, a launch string or `sed s/../../`. */
export const SAFE_SECRET = /^[A-Za-z0-9._@:+=,%^-]{1,64}$/;
/** Map names and similar identifiers. */
export const SAFE_ID = /^[A-Za-z0-9_]{1,64}$/;

/** A free-text name written inside double quotes in a game cfg / passed in a launch string. */
export function safeName(v: string): boolean {
  return v.length > 0 && v.length <= 128 && !/["\\;\r\n\0`$]/.test(v) && !v.includes("//");
}

const shellQuote = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

/**
 * Read `+name value` out of a srcds launch string (gmod's GAME_PARAMS).
 * Values are single tokens or "quoted".
 */
export function getLaunchParam(params: string, name: string): string | undefined {
  const m = new RegExp(`(?:^|\\s)\\+${name}\\s+(?:"([^"]*)"|(\\S+))`).exec(params);
  return m ? (m[1] ?? m[2]) : undefined;
}

/** Set (or remove with null) `+name value` in a launch string, leaving every other token untouched. */
export function setLaunchParam(params: string, name: string, value: string | null): string {
  const re = new RegExp(`(?:^|\\s)\\+${name}\\s+(?:"[^"]*"|\\S+)`, "g");
  const stripped = params.replace(re, "").replace(/\s{2,}/g, " ").trim();
  if (value === null) return stripped;
  return `${stripped}${stripped ? " " : ""}+${name} ${value}`;
}

/**
 * Put `-e KEY='value'` in a docker setup script: replace the flag when it is already there, otherwise
 * insert it right after `docker run -d`. null removes the flag. Values are single-quote escaped.
 */
export function setEnvInScript(script: string, key: string, value: string | null): string {
  const re = new RegExp(`-e\\s+${key}=(?:'[^']*'|"[^"]*"|\\S*)`);
  if (value === null) return script.replace(re, "").replace(/\s{2,}/g, " ");
  const flag = `-e ${key}=${shellQuote(value)}`;
  if (re.test(script)) return script.replace(re, () => flag);
  return script.replace(/(docker run\s+(?:-d|--detach)\b)/, (_m, a) => `${a} ${flag}`);
}

/** Read `-e KEY=value` back out of a setup script (quotes stripped). */
export function scriptEnvValue(script: string, key: string): string | null {
  const m = new RegExp(`-e\\s+${key}=(?:'([^']*)'|"([^"]*)"|(\\S*))`).exec(script);
  return m ? (m[1] ?? m[2] ?? m[3] ?? "") : null;
}

/** Run `cmd` before the first `docker run` of a setup script (`A && B && docker run ...` shape). */
export function prependBeforeDockerRun(script: string, cmd: string): string {
  return script.replace(/docker run\s+(?:-d|--detach)\b/, (m) => `${cmd} && ${m}`);
}

export type CfgEdit = { key: string; value: string; quote?: boolean };

/**
 * Source `key value` cfg patcher (server.cfg). Replaces the FIRST line whose first token is `key`
 * (case-insensitive), drops any later duplicates, keeps every comment and unknown line, appends a missing
 * key at the end. `quote` writes `key "value"`. With `onlyIfPresent` a missing key is not appended.
 */
export function patchCfgLines(content: string, edits: (CfgEdit & { onlyIfPresent?: boolean })[]): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const lines = content.length ? content.split(/\r?\n/) : [];
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  for (const e of edits) {
    const text = `${e.key} ${e.quote ? `"${e.value}"` : e.value}`;
    const isKey = (l: string) => {
      const t = l.trim();
      if (!t || t.startsWith("//") || t.startsWith("#")) return false;
      return t.split(/\s+/)[0].toLowerCase() === e.key.toLowerCase();
    };
    const first = lines.findIndex(isKey);
    if (first < 0) {
      if (!e.onlyIfPresent) lines.push(text);
      continue;
    }
    lines[first] = text;
    for (let i = lines.length - 1; i > first; i--) if (isKey(lines[i])) lines.splice(i, 1);
  }
  return lines.join(eol) + eol;
}

/** Read `key value` / `key "value"` back out of a cfg (first match). */
export function readCfgValue(content: string, key: string): string | undefined {
  for (const l of content.split(/\r?\n/)) {
    const t = l.trim();
    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
    const m = /^(\S+)\s+(?:"([^"]*)"|(\S+))/.exec(t);
    if (m && m[1].toLowerCase() === key.toLowerCase()) return m[2] ?? m[3];
    if (m === null && t.toLowerCase() === key.toLowerCase()) return "";
  }
  return undefined;
}

/** "true"/"false"/boolean -> boolean. */
export const asBool = (v: unknown) => v === true || String(v).toLowerCase() === "true";
export const str = (v: unknown) => (v === undefined || v === null ? "" : String(v));

