/** What one family wants changed on the container + which schema fields that covers. */
export type EnvPlan = { env: Record<string, string | null>; fields: string[]; errors: string[]; notes: string[] };
export const emptyPlan = (): EnvPlan => ({ env: {}, fields: [], errors: [], notes: [] });

/**
 * A credential-like env var. `explicit` = the customer changed it in THIS save (otherwise the job was auto-queued
 * at provision and a BLANK value must never overwrite whatever the container already carries).
 *  - blank + not explicit: skipped
 *  - blank + refuseBlank:   refused (a blank would silently disable / reset the credential)
 *  - blank otherwise:       `blankAs` (null removes the var so the image default returns, "" sets it empty)
 */
export function planSecret(
  p: EnvPlan,
  o: { field: string; label: string; envKey: string; value: string; explicit: boolean; pattern: RegExp; refuseBlank?: boolean; blankAs?: string | null },
): void {
  const v = o.value;
  if (v === "") {
    if (!o.explicit) return;
    if (o.refuseBlank) {
      p.notes.push(`${o.label} can't be blank on this server, so the current one was kept.`);
      return;
    }
    p.env[o.envKey] = o.blankAs === undefined ? "" : o.blankAs;
    p.fields.push(o.field);
    return;
  }
  if (!o.pattern.test(v)) {
    p.errors.push(`${o.label} may only contain letters, numbers and . _ @ : + = , % ^ - (max 64 characters).`);
    return;
  }
  p.env[o.envKey] = v;
  p.fields.push(o.field);
}
EOF
