import type { GameConfigApplierSpec } from "../game-config-appliers";
import { SAFE_SECRET, asBool, emptyPlan, planSecret, str, type EnvPlan, type V } from "./source-common";

/**
 * Counter-Strike 2 (joedwards32/cs2) — PURE half.
 *
 * Truth, read off the image's own entry.sh (steamrt4/etc/entry.sh) and README:
 *  - the image REWRITES game/csgo/cfg/server.cfg from its own template on EVERY boot
 *    (`cp /etc/server.cfg ...; sed -i {{SERVER_HOSTNAME}}/{{SERVER_PW}}/{{SERVER_RCON_PW}}...`). The old inline
 *    applyCs2 wrote cvars into that file over SFTP: they were wiped at the next start, so it was never a durable
 *    mechanism. Settings must go through the container's environment.
 *  - game mode: `+game_alias $CS2_GAMEALIAS` when set, else `+game_type $CS2_GAMETYPE +game_mode $CS2_GAMEMODE`.
 *    We always set the numeric pair and clear the alias (all five modes have a numeric pair).
 *  - bots: CS2_BOT_QUOTA is sed-ed into every cfg/gamemode_*.cfg at boot (`bot_quota` lines).
 *  - SRCDS_TOKEN -> `+sv_setsteamaccount`, CS2_PW -> `+sv_password`, CS2_RCONPW -> `+rcon_password` (and
 *    {{SERVER_RCON_PW}} in server.cfg, which is where lib/game-control.ts reads it for the player list).
 *  - maxrounds (mp_maxrounds): NO env var exists, server.cfg is regenerated at boot and gamemode_*_server.cfg is
 *    the file CS2 re-executes per mode (not verified on a live box). Saved only, on purpose.
 *
 * Status: built from the image's source, NOT run against a real server.
 */
export const CS2_SPEC: GameConfigApplierSpec = {
  family: "cs2",
  fields: {
    game_mode: { when: "recreate", note: "Applies on save with a brief restart (the container is rebuilt with the new mode)." },
    bots: { when: "recreate", note: "Sets the bot quota (10 when on, 0 when off). Applies on save with a brief restart; the image writes it into the game-mode configs when it starts." },
    SRCDS_TOKEN: { when: "recreate", secret: true, note: "Clearing this unlists the server from the Steam browser." },
    CS2_PW: { when: "recreate", secret: true },
    CS2_RCONPW: { when: "recreate", secret: true, note: "Can't be blank: RCON stays on with a password." },
  },
};

export const CS2_CONTAINER = "cs2";
export const CS2_ENV_FILE = "/root/cs2.env";

export const CS2_GAME_MODE: Record<string, { type: string; mode: string }> = {
  competitive: { type: "0", mode: "1" },
  wingman: { type: "0", mode: "2" },
  casual: { type: "0", mode: "0" },
  deathmatch: { type: "1", mode: "2" },
  custom: { type: "3", mode: "0" },
};

export const CS2_BOT_QUOTA_ON = "10";

/** Env the container must carry for the touched fields (explicit = changed in this save). */
export function cs2EnvPlan(values: V, touched: readonly string[], explicit: boolean): EnvPlan {
  const p = emptyPlan();
  if (touched.includes("game_mode") && values.game_mode !== undefined) {
    const gm = CS2_GAME_MODE[str(values.game_mode)];
    if (gm) {
      p.env.CS2_GAMEALIAS = "";
      p.env.CS2_GAMETYPE = gm.type;
      p.env.CS2_GAMEMODE = gm.mode;
      p.fields.push("game_mode");
    }
  }
  if (touched.includes("bots") && values.bots !== undefined) {
    p.env.CS2_BOT_QUOTA = asBool(values.bots) ? CS2_BOT_QUOTA_ON : "0";
    p.fields.push("bots");
  }
  if (touched.includes("SRCDS_TOKEN") && values.SRCDS_TOKEN !== undefined) {
    const t = str(values.SRCDS_TOKEN).trim();
    if (t !== "" && !/^[A-Za-z0-9]{1,64}$/.test(t)) p.errors.push("The Game Server Login Token may only contain letters and numbers.");
    else if (t === "") {
      if (explicit) { p.env.SRCDS_TOKEN = ""; p.fields.push("SRCDS_TOKEN"); }
    } else { p.env.SRCDS_TOKEN = t; p.fields.push("SRCDS_TOKEN"); }
  }
  if (touched.includes("CS2_PW") && values.CS2_PW !== undefined) {
    planSecret(p, { field: "CS2_PW", label: "The server password", envKey: "CS2_PW", value: str(values.CS2_PW), explicit, pattern: SAFE_SECRET, blankAs: "" });
  }
  if (touched.includes("CS2_RCONPW") && values.CS2_RCONPW !== undefined) {
    planSecret(p, { field: "CS2_RCONPW", label: "The RCON password", envKey: "CS2_RCONPW", value: str(values.CS2_RCONPW), explicit, pattern: SAFE_SECRET, refuseBlank: true });
  }
  return p;
}
EOF

