import type { GameConfigApplierSpec } from "../game-config-appliers";
import { SAFE_ID, SAFE_SECRET, emptyPlan, planSecret, safeName, str, type CfgEdit, type EnvPlan, type V } from "./source-common";

/**
 * Team Fortress 2 (cm2network/tf2) — PURE half.
 *
 * Truth, read off the image's etc/entry.sh and README:
 *  - srcds_run is started with `+maxplayers $SRCDS_MAXPLAYERS +map $SRCDS_STARTMAP +sv_setsteamaccount $SRCDS_TOKEN
 *    +rcon_password $SRCDS_RCONPW +sv_password $SRCDS_PW -tickrate $SRCDS_TICKRATE`: all env, read at every start.
 *  - SRCDS_HOSTNAME is "first launch only": entry.sh only sed-replaces `{{SERVER_HOSTNAME}}` in
 *    tf/cfg/server.cfg, once. There is NO launch arg for it, so the name lives in server.cfg (`hostname "..."`).
 *  - the image's stock server.cfg sets `rcon_password changeme`, and server.cfg is exec'd AFTER the launch args
 *    (the README says so: "value can be overwritten by tf/cfg/server.cfg"), so the effective RCON password is
 *    whatever server.cfg says. We therefore write rcon_password into server.cfg too, so it always matches the env
 *    value that lib/game-control.ts reads for the player list. Stock server.cfg also has `sv_visiblemaxplayers 24`
 *    (reports max 24 to browsers): kept in step with Max Players when that line exists.
 *  - with the bind mount over tf-dedicated the image's own server.cfg copy may not be there; a missing file is
 *    created with just these lines (a missing server.cfg is simply not executed, so that is safe).
 *
 * Status: built from the image's source, NOT run against a real server.
 */
export const TF2_SPEC: GameConfigApplierSpec = {
  family: "tf2",
  fields: {
    SRCDS_HOSTNAME: { when: "restart", note: "Written to the server's server.cfg; shown after the next restart." },
    SRCDS_MAXPLAYERS: { when: "recreate" },
    SRCDS_RCONPW: { when: "recreate", secret: true, note: "Can't be blank: RCON stays on with a password." },
    SRCDS_TOKEN: { when: "recreate", secret: true },
    SRCDS_STARTMAP: { when: "recreate", note: "Letters, numbers and underscores only (e.g. ctf_2fort)." },
    SRCDS_PW: { when: "recreate", secret: true },
    SRCDS_TICKRATE: { when: "recreate" },
  },
};

export const TF2_CONTAINER = "tf2";
export const TF2_ENV_FILE = "/root/tf2.env";
export const TF2_SERVER_CFG = "/opt/tf2/tf/cfg/server.cfg";

export function tf2EnvPlan(values: V, touched: readonly string[], explicit: boolean): EnvPlan {
  const p = emptyPlan();
  const has = (k: string) => touched.includes(k) && values[k] !== undefined;
  if (has("SRCDS_MAXPLAYERS")) {
    const n = Number(values.SRCDS_MAXPLAYERS);
    if (Number.isInteger(n) && n >= 2 && n <= 32) { p.env.SRCDS_MAXPLAYERS = String(n); p.fields.push("SRCDS_MAXPLAYERS"); }
    else p.errors.push("Max Players must be a whole number between 2 and 32.");
  }
  if (has("SRCDS_STARTMAP")) {
    const m = str(values.SRCDS_STARTMAP).trim();
    if (SAFE_ID.test(m)) { p.env.SRCDS_STARTMAP = m; p.fields.push("SRCDS_STARTMAP"); }
    else p.errors.push("The starting map may only contain letters, numbers and underscores.");
  }
  if (has("SRCDS_TICKRATE")) {
    const t = str(values.SRCDS_TICKRATE);
    if (t === "66" || t === "100") { p.env.SRCDS_TICKRATE = t; p.fields.push("SRCDS_TICKRATE"); }
    else p.errors.push("Tick rate must be 66 or 100.");
  }
  if (has("SRCDS_TOKEN")) {
    const t = str(values.SRCDS_TOKEN).trim();
    if (t !== "" && !/^[A-Za-z0-9]{1,64}$/.test(t)) p.errors.push("The GSLT token may only contain letters and numbers.");
    else if (t === "") { if (explicit) { p.env.SRCDS_TOKEN = null; p.fields.push("SRCDS_TOKEN"); } } // null = the image's own default ("0")
    else { p.env.SRCDS_TOKEN = t; p.fields.push("SRCDS_TOKEN"); }
  }
  // The image's default server password is the literal "changeme": a blank must be written as an EMPTY value, never removed.
  if (has("SRCDS_PW")) planSecret(p, { field: "SRCDS_PW", label: "The server password", envKey: "SRCDS_PW", value: str(values.SRCDS_PW), explicit, pattern: SAFE_SECRET, blankAs: "" });
  if (has("SRCDS_RCONPW")) planSecret(p, { field: "SRCDS_RCONPW", label: "The RCON password", envKey: "SRCDS_RCONPW", value: str(values.SRCDS_RCONPW), explicit, pattern: SAFE_SECRET, refuseBlank: true });
  return p;
}

/** The server.cfg lines for the touched fields (hostname, rcon_password, sv_visiblemaxplayers). */
export function tf2CfgPlan(values: V, touched: readonly string[]): { edits: (CfgEdit & { onlyIfPresent?: boolean })[]; fields: string[]; errors: string[] } {
  const edits: (CfgEdit & { onlyIfPresent?: boolean })[] = [];
  const fields: string[] = [];
  const errors: string[] = [];
  if (touched.includes("SRCDS_HOSTNAME") && values.SRCDS_HOSTNAME !== undefined) {
    const h = str(values.SRCDS_HOSTNAME).trim();
    if (safeName(h)) { edits.push({ key: "hostname", value: h, quote: true }); fields.push("SRCDS_HOSTNAME"); }
    else errors.push('The server name can\'t be blank or contain " ; \\ // or line breaks.');
  }
  if (touched.includes("SRCDS_RCONPW") && values.SRCDS_RCONPW !== undefined && SAFE_SECRET.test(str(values.SRCDS_RCONPW))) {
    edits.push({ key: "rcon_password", value: str(values.SRCDS_RCONPW), quote: true });
    fields.push("SRCDS_RCONPW");
  }
  if (touched.includes("SRCDS_MAXPLAYERS") && values.SRCDS_MAXPLAYERS !== undefined) {
    const n = Number(values.SRCDS_MAXPLAYERS);
    if (Number.isInteger(n) && n >= 2 && n <= 32) edits.push({ key: "sv_visiblemaxplayers", value: String(n), onlyIfPresent: true });
  }
  return { edits, fields, errors };
}
