import type { GameConfigApplierSpec } from "../game-config-appliers";
import { SAFE_ID, SAFE_SECRET, asBool, emptyPlan, planSecret, str, type EnvPlan, type V } from "./source-common";

/**
 * Left 4 Dead 2 (left4devops/l4d2) — PURE half.
 *
 * Truth, read off the image's entrypoint.sh (Left4DevOps/l4d2-docker): srcds_run is assembled at every start from env:
 * `+hostname "$HOSTNAME"`, `+map "$DEFAULT_MAP $DEFAULT_MODE"`, `+sv_gametypes "$GAME_TYPES"` (only if set),
 * `+sv_steamgroup $STEAM_GROUP` (only if > 0), `+sv_steamgroup_exclusive 1` when STEAM_GROUP_EXCLUSIVE is NON-EMPTY
 * (the string "false" counts as true, so off = the variable removed), `+rcon_password "$RCON_PASSWORD"` (only if set).
 * No cfg file is involved, so every field is an env var and a change needs the container rebuilt.
 * Status: built from the image's source, NOT run against a real server.
 */
export const L4D2_SPEC: GameConfigApplierSpec = {
  family: "l4d2",
  fields: {
    HOSTNAME: { when: "recreate" },
    DEFAULT_MODE: { when: "recreate", note: "The mode the server loads on start; players can still pick another from the lobby." },
    RCON_PASSWORD: { when: "recreate", secret: true, note: "Can't be blank: RCON stays on with a password." },
    DEFAULT_MAP: { when: "recreate", note: "The map the server loads on start (e.g. c1m1_hotel)." },
    GAME_TYPES: { when: "recreate", note: "Comma-separated, lowercase. Blank allows every mode." },
    STEAM_GROUP: { when: "recreate", note: "A numeric Steam group ID; blank or 0 turns it off." },
    STEAM_GROUP_EXCLUSIVE: { when: "recreate" },
  },
};

export const L4D2_CONTAINER = "l4d2";
export const L4D2_ENV_FILE = "/root/l4d2.env";
const MODES = ["coop", "versus", "realism", "survival", "scavenge", "dash", "holdout", "shootzones"];

export function l4d2EnvPlan(values: V, touched: readonly string[], explicit: boolean): EnvPlan {
  const p = emptyPlan();
  const has = (k: string) => touched.includes(k) && values[k] !== undefined;
  if (has("HOSTNAME")) {
    const h = str(values.HOSTNAME).trim();
    if (h && h.length <= 128 && !/["\;\r\n\0`$]/.test(h)) { p.env.HOSTNAME = h; p.fields.push("HOSTNAME"); }
    else p.errors.push('The server name can\'t be blank or contain " ; \\ $ or line breaks.');
  }
  if (has("DEFAULT_MODE")) {
    const m = str(values.DEFAULT_MODE);
    if (MODES.includes(m)) { p.env.DEFAULT_MODE = m; p.fields.push("DEFAULT_MODE"); }
    else p.errors.push("Unknown game mode.");
  }
  if (has("DEFAULT_MAP")) {
    const m = str(values.DEFAULT_MAP).trim();
    if (SAFE_ID.test(m)) { p.env.DEFAULT_MAP = m; p.fields.push("DEFAULT_MAP"); }
    else p.errors.push("The starting map may only contain letters, numbers and underscores.");
  }
  if (has("GAME_TYPES")) {
    const g = str(values.GAME_TYPES).replace(/\s+/g, "").toLowerCase();
    if (g === "") { p.env.GAME_TYPES = null; p.fields.push("GAME_TYPES"); }
    else if (/^[a-z0-9_]+(,[a-z0-9_]+)*$/.test(g) && g.length <= 200) { p.env.GAME_TYPES = g; p.fields.push("GAME_TYPES"); }
    else p.errors.push("Allowed vote modes must be a comma-separated list like coop,versus.");
  }
  if (has("STEAM_GROUP")) {
    const g = str(values.STEAM_GROUP).trim();
    if (g === "") { p.env.STEAM_GROUP = "0"; p.fields.push("STEAM_GROUP"); }
    else if (/^\d{1,12}$/.test(g)) { p.env.STEAM_GROUP = String(Number(g)); p.fields.push("STEAM_GROUP"); }
    else p.errors.push("The Steam group must be a number (its group ID).");
  }
  if (has("STEAM_GROUP_EXCLUSIVE")) {
    // The image treats ANY non-empty value as on, so off must remove the variable entirely.
    p.env.STEAM_GROUP_EXCLUSIVE = asBool(values.STEAM_GROUP_EXCLUSIVE) ? "true" : null;
    p.fields.push("STEAM_GROUP_EXCLUSIVE");
  }
  if (has("RCON_PASSWORD")) planSecret(p, { field: "RCON_PASSWORD", label: "The RCON password", envKey: "RCON_PASSWORD", value: str(values.RCON_PASSWORD), explicit, pattern: SAFE_SECRET, refuseBlank: true });
  return p;
}
EOF

