import type { GameConfigApplierSpec } from "../game-config-appliers";
import { SAFE_SECRET, getLaunchParam, safeName, setLaunchParam, str, type CfgEdit, type V } from "./source-common";

/**
 * Garry's Mod (ghcr.io/ich777/steamcmd:garrysmod) — PURE half.
 *
 * Truth, read off the image's scripts/start-server.sh: the server is started as
 * `srcds_run -game garrysmod ${GAME_PARAMS} -console +port ${GAME_PORT}`, with GAME_PARAMS one env string
 * (setup script: `-secure +gamemode sandbox +map gm_construct +maxplayers 16`). The string is expanded UNQUOTED, so
 * only single-token values are safe in it:
 *  - max_players -> `+maxplayers N`, gslt_token -> `+sv_setsteamaccount T`, sv_password -> `+sv_password P`,
 *    rcon_password -> `+rcon_password P` rewritten inside GAME_PARAMS (container rebuilt). Every other token
 *    (gamemode, map, -secure) is left alone.
 *  - hostname has spaces, so it can't ride in GAME_PARAMS: it goes in garrysmod/cfg/server.cfg (`hostname "..."`),
 *    the file srcds executes at start. Created if missing. Note the image starts with VALIDATE=true: if Steam's
 *    file validation ever reverts that file the name falls back to the default (not observed, not verified).
 *  - workshop_collection: `+host_workshop_collection` only works together with a Steam Web API key (`-authkey`),
 *    which the platform does not have per server. Saved only, on purpose.
 * Status: built from the image's source, NOT run against a real server.
 */
export const GMOD_SPEC: GameConfigApplierSpec = {
  family: "gmod",
  fields: {
    hostname: { when: "restart", note: "Written to garrysmod/cfg/server.cfg; shown after the next restart." },
    max_players: { when: "recreate" },
    sv_password: { when: "recreate", secret: true, note: "Letters, numbers and . _ @ : + = , % ^ - only. Blank = open server." },
    gslt_token: { when: "recreate", secret: true },
    rcon_password: { when: "recreate", secret: true, note: "Letters, numbers and . _ @ : + = , % ^ - only." },
  },
};

export const GMOD_CONTAINER = "gmod";
export const GMOD_ENV_FILE = "/root/gmod.env";
export const GMOD_SERVER_CFG = "/opt/gmod/garrysmod/cfg/server.cfg";
export const GMOD_DEFAULT_PARAMS = "-secure +gamemode sandbox +map gm_construct +maxplayers 16";

/** GAME_PARAMS rewrite for the touched launch-arg fields. Returns null when nothing in it changes. */
export function gmodParamsPlan(oldParams: string, values: V, touched: readonly string[], explicit: boolean): { params: string; fields: string[]; errors: string[]; notes: string[] } {
  let params = oldParams;
  const fields: string[] = [];
  const errors: string[] = [];
  const notes: string[] = [];
  const has = (k: string) => touched.includes(k) && values[k] !== undefined;
  if (has("max_players")) {
    const n = Number(values.max_players);
    if (Number.isInteger(n) && n >= 2 && n <= 128) { params = setLaunchParam(params, "maxplayers", String(n)); fields.push("max_players"); }
