export function cs16CfgPlan(values: V, touched: readonly string[], explicit: boolean): { edits: (CfgEdit & { onlyIfPresent?: boolean })[]; fields: string[]; errors: string[] } {
  const edits: (CfgEdit & { onlyIfPresent?: boolean })[] = [];
  const fields: string[] = [];
  const errors: string[] = [];
  const has = (k: string) => touched.includes(k) && values[k] !== undefined;
  if (has("serverName")) {
    const h = str(values.serverName).trim();
    if (safeName(h)) { edits.push({ key: "hostname", value: h, quote: true }); fields.push("serverName"); }
    else errors.push('The server name can\'t be blank or contain " ; \\ // or line breaks.');
  }
  if (has("fastDownloadUrl")) {
    const u = str(values.fastDownloadUrl).trim();
    if (u === "" || (/^https?:\/\/[^\s"';\\]+$/.test(u) && u.length <= 200)) { edits.push({ key: "sv_downloadurl", value: u, quote: true }); fields.push("fastDownloadUrl"); }
    else errors.push("The fast download URL must start with http:// or https:// and contain no spaces or quotes.");
  }
  if (has("rconPassword")) {
    const v = str(values.rconPassword);
    if (v === "") { if (explicit) { edits.push({ key: "rcon_password", value: "", quote: true }); fields.push("rconPassword"); } }
    else if (SAFE_SECRET.test(v)) { edits.push({ key: "rcon_password", value: v, quote: true }); fields.push("rconPassword"); }
    else errors.push("The RCON password may only contain letters, numbers and . _ @ : + = , % ^ - (max 64 characters).");
  }
