export function patchAmxxAdmin(content: string, steamId: string): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const lines = content.split(/\r?\n/).filter((l) => !l.includes(CS16_ADMIN_MARK) && !l.includes(BUILD_ADMIN_MARK));
  while (lines.length && lines[lines.length - 1] === "") lines.pop();
  if (steamId) lines.push(`"${steamId}" "" "abcdefghijklmnopqrstu" "ce" ${CS16_ADMIN_MARK}`);
  return lines.join(eol) + eol;
}
export const validSteamId = (s: string) => s === "" || STEAMID.test(s);
export function readAmxxAdmin(content: string): string {
  const l = content.split(/\r?\n/).find((x) => x.includes(CS16_ADMIN_MARK));
  return l ? (/^\s*"([^"]*)"/.exec(l)?.[1] ?? "") : "";
}
