import { GAME_CONFIG_SCHEMAS } from "../../lib/game-config";
import type { EnvPlan } from "../../lib/game-applier-specs/source-common";
import type { ApplierContext, ApplyOutcome, Guest } from "./types";
import { shq } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { recreateWithEnv } from "./kit/env-recreate";

/**
 * The shared engine for the Source-engine family appliers (cs2, cs16, tf2, l4d2, gmod, kf2). A family file only
 * says WHICH env vars and WHICH files change for the touched fields (pure plans in
 * lib/game-applier-specs/<family>.ts); this runs them with the safety shape every applier here shares:
 *
 *   validate (a bad value changes nothing) -> patch files (backup, verify, create if the file is missing and
 *   `create` is set) -> rebuild the container with the new env (old one kept until the new one verifies) ->
 *   if the rebuild fails every file edit is put back, so a failure always means "nothing changed".
 */
export type FileJob = {
  path: string;
  fields: string[];
  patch(old: string): string;
  /** Make the file when it does not exist yet (cfg files only; the parent folder must exist). */
  create?: boolean;
  validate?(content: string): string | null;
};

export type SourcePlan = {
  container: string;
  envFile: string;
  /** Env changes for the touched fields; `cur` is the container's current env (null if it could not be read). */
  env(cur: Map<string, string> | null): EnvPlan;
  files: FileJob[];
  /** Extra errors (from the file plans) reported before anything is touched. */
  errors?: string[];
  /** After a successful, running recreate: confirm in the game's own files. Return customer-facing notes. */
  verify?(guest: Guest): Promise<string[]>;
};

export async function readContainerEnv(guest: Guest, container: string): Promise<Map<string, string> | null> {
  const r = await guest.exec(`docker inspect ${shq(container)} --format '{{json .}}'`);
  if (r.code !== 0) return null;
  try {
    const o = JSON.parse(r.stdout.trim());
    const env = new Map<string, string>();
    for (const e of (o.Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) env.set(e.slice(0, i), e.slice(i + 1));
    }
    return env;
  } catch {
    return null;
  }
}

const labelOf = (family: string, key: string) => GAME_CONFIG_SCHEMAS[family]?.fields.find((f) => f.key === key)?.label ?? key;
const list = (family: string, keys: string[]) => keys.map((k) => labelOf(family, k)).join(", ");

export async function runSourcePlan(ctx: ApplierContext, plan: SourcePlan): Promise<ApplyOutcome> {
  const { guest, family } = ctx;
  const cur = await readContainerEnv(guest, plan.container);
  const envPlan = plan.env(cur);
  const errors = [...(plan.errors ?? []), ...envPlan.errors];
  if (errors.length) return { ok: false, applied: [], notes: [...errors, "Nothing was changed on your server."] };

  const applied: string[] = [];
  const notes: string[] = [...envPlan.notes];
  const undo: (() => Promise<void>)[] = [];
  const commits: (() => Promise<void>)[] = [];
  const rollback = async () => {
    for (const u of undo.reverse()) await u().catch(() => undefined);
  };

  // ---- files ---------------------------------------------------------------
  for (const job of plan.files) {
    if (!job.fields.length) continue;
    const old = await guest.readFile(job.path);
    if (old === null) {
      if (!job.create) {
        notes.push(`${list(family, job.fields)} could not be applied: the game hasn't created ${job.path} yet (start the server once, then save again).`);
        continue;
      }
      try {
        const next = job.patch("");
        const bad = job.validate?.(next);
        if (bad) throw new Error(bad);
        await guest.writeFile(job.path, next);
        if ((await guest.readFile(job.path)) !== next) throw new Error("did not verify");
        undo.push(async () => void (await guest.exec(`rm -f ${shq(job.path)}`)));
        applied.push(`Created ${job.path} with ${list(family, job.fields)}.`);
      } catch {
        await rollback();
        return { ok: false, applied: [], notes: [`Could not create ${job.path} (the game files may not be installed yet), so nothing was changed on your server.`] };
      }
      continue;
    }
    const res = await patchRemoteFile(guest, { path: job.path, patch: job.patch, validate: job.validate });
    if (res.status === "invalid" || res.status === "failed") {
      await rollback();
      return { ok: false, applied: [], notes: [res.reason, "Nothing was changed on your server."] };
    }
    if (res.status === "unchanged") {
      notes.push(`${list(family, job.fields)} already matched the server's files.`);
    } else if (res.status === "changed") {
      undo.push(res.restore);
      commits.push(res.commit);
      applied.push(`Updated ${list(family, job.fields)} in ${job.path}.`);
    }
  }

  // ---- container env -----------------------------------------------------------
  let restarted = false;
  const envKeys = Object.keys(envPlan.env);
  if (envKeys.length) {
    const r = await recreateWithEnv(guest, {
      container: plan.container,
      unit: ctx.unit,
      env: envPlan.env,
      envFile: plan.envFile,
      waitPort: ctx.waitPort,
    });
    if (r.status === "failed") {
      await rollback();
      return { ok: false, applied: [], notes: [r.note, ...(undo.length ? ["Your file changes were put back as well, so nothing was changed."] : [])] };
    }
    if (r.status === "recreated") {
      restarted = r.wasActive;
      applied.push(`Rebuilt your server with the new ${list(family, envPlan.fields)}.`);
      notes.push(...r.notes);
      if (r.wasActive) notes.push("Your server restarted briefly to apply this; connected players were disconnected and can rejoin now.");
      if (r.wasActive && plan.verify) notes.push(...(await plan.verify(guest).catch(() => [])));
    } else {
      notes.push(`Your server is already running with these ${list(family, envPlan.fields)} settings; nothing to rebuild.`);
    }
  }

  for (const c of commits) await c().catch(() => undefined);
  return { ok: true, applied, notes, restarted };
}
