import { runApplier } from "../worker/game-config-appliers/run";
import type { GameConfigApplier } from "../worker/game-config-appliers/types";
import { validateConfig } from "../lib/game-config";
import { fakeGuest } from "./_fake-docker-guest";

/** A fake guest whose game container looks like the family's real one (image env, args, mounts). */
export function srcGuest(o: { container: string; image: string; env?: string[]; cmd?: string[]; binds?: string[]; files?: Record<string, string>; active?: boolean; createFails?: boolean; startFailsForNew?: boolean }) {
  const g = fakeGuest({ container: o.container, unit: `${o.container}.service`, files: o.files, active: o.active, createFails: o.createFails, startFailsForNew: o.startFailsForNew });
  const c = g.containers.get(o.container)!;
  c.image = o.image;
  c.env = ["PATH=/usr/bin", ...(o.env ?? [])];
  c.cmd = o.cmd ?? [];
  c.binds = (o.binds ?? []).slice().sort();
  c.ports = { "27015/tcp": [{ HostIp: "", HostPort: "27015" }], "27015/udp": [{ HostIp: "", HostPort: "27015" }] };
  return g;
}

export const defaultsFor = (family: string) => (validateConfig(family, {}) as { ok: true; values: Record<string, string | number | boolean> }).values;

export function runFam(applier: GameConfigApplier, g: ReturnType<typeof fakeGuest>, values: Record<string, string | number | boolean>, changed: string[] | undefined, restartRequested = false) {
  return runApplier(applier, { server: { id: "s1" }, values, changed, restartRequested, guest: g.guest, unit: g.unit, waitPort: async () => ({ ok: true }) });
}

export const envOf = (g: ReturnType<typeof fakeGuest>, name: string) => {
  const m = new Map<string, string>();
  for (const e of g.containers.get(name)!.env) { const i = e.indexOf("="); if (i > 0) m.set(e.slice(0, i), e.slice(i + 1)); }
  return m;
};
