const STOCK = `// General Settings //\n\n// Hostname for server.\nhostname "{{SERVER_HOSTNAME}}"\n\nsv_visiblemaxplayers 24\nmp_maxrounds 5\n\n// Rcon\nrcon_password changeme\nsv_rcon_banpenalty 1440\n`;
