  srcGuest({ container: "tf2", image: "cm2network/tf2:latest", env: ["SRCDS_TOKEN=", "SRCDS_RCONPW=oldrcon1", "SRCDS_HOSTNAME=Nxeon TF2", "SRCDS_MAXPLAYERS=24", "SRCDS_PW=changeme", "SRCDS_STARTMAP=ctf_2fort", "SRCDS_TICKRATE=66"], binds: ["/opt/tf2:/home/steam/tf-dedicated"], files, ...o });
const V = (over: Record<string, string | number | boolean> = {}) => ({ ...defaultsFor("tf2"), ...over });

test("tf2: every schema field is mapped", () => {
  assert.deepEqual(GAME_CONFIG_SCHEMAS.tf2.fields.map((f) => f.key).filter((k) => !(k in TF2_SPEC.fields)), []);
});
test("tf2: each launch env field is applied through a container rebuild", async () => {
  const cases: [string, string | number, string, string][] = [
    ["SRCDS_MAXPLAYERS", 30, "SRCDS_MAXPLAYERS", "30"],
    ["SRCDS_STARTMAP", "pl_badwater", "SRCDS_STARTMAP", "pl_badwater"],
    ["SRCDS_TICKRATE", "100", "SRCDS_TICKRATE", "100"],
    ["SRCDS_TOKEN", "ABCD1234EFGH", "SRCDS_TOKEN", "ABCD1234EFGH"],
    ["SRCDS_PW", "joinme-1", "SRCDS_PW", "joinme-1"],
  ];
  for (const [field, value, key, want] of cases) {
    const g = guest();
