    assert.equal(out.ok, true, `${field}: ${out.notes.join("|")}`);
    assert.equal(envOf(g, "tf2").get(key), want, field);
    assert.ok(g.containers.get("tf2")!.binds.includes("/opt/tf2:/home/steam/tf-dedicated"));
  }
});
