import { GMOD_SERVER_CFG, GMOD_SPEC, getLaunchParam, setLaunchParam } from "../lib/game-applier-specs/gmod";
import { readCfgValue } from "../lib/game-applier-specs/source-common";
import { applySourceSetup } from "../lib/game-applier-specs/source-setup";
import { GAME_CONFIG_SCHEMAS } from "../lib/game-config";
import { defaultsFor, envOf, runFam, srcGuest } from "./_cfg-source-helpers";

const PARAMS = "-secure +gamemode darkrp +map gm_construct +maxplayers 16";
const guest = (files: Record<string, string> = { [GMOD_SERVER_CFG]: '// gmod\nsbox_maxprops 200\nhostname "Old"\n' }, o: Record<string, unknown> = {}) =>
  srcGuest({ container: "gmod", image: "ghcr.io/ich777/steamcmd:garrysmod", env: [`GAME_PARAMS=${PARAMS}`, "GAME_ID=4020", "VALIDATE=true"], binds: ["/opt/gmod:/serverdata/serverfiles"], files, ...o });
const V = (over: Record<string, string | number | boolean> = {}) => ({ ...defaultsFor("gmod"), ...over });
const params = (g: ReturnType<typeof guest>) => envOf(g, "gmod").get("GAME_PARAMS")!;

test("gmod: all schema fields are mapped except workshop_collection (needs a Web API key)", () => {
  assert.deepEqual(GAME_CONFIG_SCHEMAS.gmod.fields.map((f) => f.key).filter((k) => !(k in GMOD_SPEC.fields)), ["workshop_collection"]);
});
test("gmod: launch-param helpers replace only their own token", () => {
  assert.equal(setLaunchParam(PARAMS, "maxplayers", "32"), "-secure +gamemode darkrp +map gm_construct +maxplayers 32");
  assert.equal(setLaunchParam(PARAMS, "sv_password", "pw"), `${PARAMS} +sv_password pw`);
  assert.equal(setLaunchParam(`${PARAMS} +sv_password pw`, "sv_password", null), PARAMS);
  assert.equal(getLaunchParam(PARAMS, "map"), "gm_construct");
});
test("gmod: max players / password / rcon / GSLT rewrite GAME_PARAMS, keeping gamemode and map", async () => {
  const g = guest();
  const out = await runFam(gmodApplier, g, V({ max_players: 40, sv_password: "joinpw-2", rcon_password: "rconpw-3", gslt_token: "ABCDEF0123456789" }), ["max_players", "sv_password", "rcon_password", "gslt_token"]);
  assert.equal(out.ok, true, out.notes.join("|"));
  const p = params(g);
  assert.match(p, /\+gamemode darkrp/);
  assert.match(p, /\+map gm_construct/);
  assert.match(p, /-secure/);
  assert.equal(getLaunchParam(p, "maxplayers"), "40");
  assert.equal(getLaunchParam(p, "sv_password"), "joinpw-2");
  assert.equal(getLaunchParam(p, "rcon_password"), "rconpw-3");
  assert.equal(getLaunchParam(p, "sv_setsteamaccount"), "ABCDEF0123456789");
  const all = JSON.stringify(out);
  for (const s of ["joinpw-2", "rconpw-3", "ABCDEF0123456789"]) assert.ok(!all.includes(s));
  assert.ok(!g.log.some((l) => /joinpw-2|rconpw-3|ABCDEF0123456789/.test(l) && !l.startsWith("write ")));
  assert.equal(envOf(g, "gmod").get("VALIDATE"), "true", "other env kept");
});
test("gmod: clearing the password removes the token (open server)", async () => {
  const g = guest(undefined, { env: [`GAME_PARAMS=${PARAMS} +sv_password old`] });
  await runFam(gmodApplier, g, V({ sv_password: "" }), ["sv_password"]);
  assert.equal(getLaunchParam(params(g), "sv_password"), undefined);
});
test("gmod: hostname is written to server.cfg (no rebuild), other lines kept", async () => {
  const g = guest();
  const out = await runFam(gmodApplier, g, V({ hostname: "My Sandbox" }), ["hostname"]);
  assert.equal(out.ok, true);
  const cfg = g.files.get(GMOD_SERVER_CFG)!;
  assert.equal(readCfgValue(cfg, "hostname"), "My Sandbox");
  assert.ok(cfg.includes("sbox_maxprops 200"));
  assert.equal(g.st.created, 0);
});
test("gmod: a missing server.cfg is created", async () => {
  const g = guest({});
  const out = await runFam(gmodApplier, g, V({ hostname: "Fresh" }), ["hostname"]);
  assert.equal(out.ok, true);
  assert.equal(readCfgValue(g.files.get(GMOD_SERVER_CFG)!, "hostname"), "Fresh");
});
test("gmod: bad values change nothing; no-op; rollback restores the cfg", async () => {
  const g = guest();
  for (const bad of [{ sv_password: "a b" }, { hostname: 'x"y' }, { max_players: 500 }, { gslt_token: "zz!" }]) {
    assert.equal((await runFam(gmodApplier, g, V(bad), Object.keys(bad))).ok, false, JSON.stringify(bad));
  }
  assert.equal(g.st.created, 0);
  await runFam(gmodApplier, g, V({ max_players: 20 }), ["max_players"]);
  const n = g.st.created;
  assert.equal((await runFam(gmodApplier, g, V({ max_players: 20 }), ["max_players"])).ok, true);
  assert.equal(g.st.created, n);
  const g2 = guest(undefined, { startFailsForNew: true });
  const before = g2.files.get(GMOD_SERVER_CFG);
  const out = await runFam(gmodApplier, g2, V({ hostname: "Z", max_players: 20 }), ["hostname", "max_players"]);
  assert.equal(out.ok, false);
  assert.equal(g2.files.get(GMOD_SERVER_CFG), before);
  assert.equal(getLaunchParam(params(g2), "maxplayers"), "16");
});
test("gmod: workshop collection alone is saved-only", async () => {
  const g = guest();
  const out = await runFam(gmodApplier, g, V({ workshop_collection: "123" }), ["workshop_collection"]);
  assert.match(out.notes.join(" "), /Saved but not applied.*workshop_collection/);
  assert.equal(g.st.created, 0);
});
test("gmod: setup bake rewrites GAME_PARAMS and seeds the hostname cfg", () => {
  const script = `curl x | sh && mkdir -p /opt/gmod && docker run -d --name gmod -e GAME_ID=4020 -e GAME_PARAMS="${PARAMS}" -e VALIDATE=true ghcr.io/ich777/steamcmd:garrysmod`;
  const out = applySourceSetup(script, "gmod", V({ max_players: 24, sv_password: "pw1", hostname: "Cool Server" }));
  assert.match(out, /-e GAME_PARAMS='-secure \+gamemode darkrp \+map gm_construct \+maxplayers 24 \+sv_password pw1'/);
  assert.match(out, /'hostname "Cool Server"'/);
  assert.ok(out.indexOf("server.cfg") < out.indexOf("docker run"));
});
EOF
