test("kf2: all fields mapped except the Workshop item id (the Mods tab owns that ini section)", () => {
  assert.deepEqual(GAME_CONFIG_SCHEMAS.kf2.fields.map((f) => f.key).filter((k) => !(k in KF2_SPEC.fields)), ["KF2_SERVER_SUBSCRIBED_WORKSHOP_ITEMS"]);
});
test("kf2: name, MOTD, web admin and admin password become container env (the image copies them into the ini on start)", async () => {
  const g = guest();
  const out = await runFam(kf2Applier, g, V({ KF2_SERVER_NAME: "Zed Hunters", KF2_SERVER_MOTD: "Welcome", KF2_WEB_ADMIN_ENABLED: false, KF2_ADMIN_PASSWORD: "adminpw-5" }), ["KF2_SERVER_NAME", "KF2_SERVER_MOTD", "KF2_WEB_ADMIN_ENABLED", "KF2_ADMIN_PASSWORD"]);
  assert.equal(out.ok, true, out.notes.join("|"));
