  assert.equal(e.get("KF2_SERVER_NAME"), "Zed Hunters");
  assert.equal(e.get("KF2_SERVER_MOTD"), "Welcome");
  assert.equal(e.get("KF2_WEB_ADMIN_ENABLED"), "false");
  assert.equal(e.get("KF2_ADMIN_PASSWORD"), "adminpw-5");
