test("kf2: honest readback: says so when the ini does not show the new value, silent when it does", async () => {
  const g = guest();
  const out = await runFam(kf2Applier, g, V({ KF2_SERVER_NAME: "Zed Hunters" }), ["KF2_SERVER_NAME"]);
  assert.match(out.notes.join(" "), /does not show the new Server Name/); // fake guest never runs the image's pre.sh
  const g2 = guest({ [KF2_GAME_INI]: GAME_INI.replace("Old", "Zed Hunters"), [KF2_WEB_INI]: WEB_INI });
  const ok = await runFam(kf2Applier, g2, V({ KF2_SERVER_NAME: "Zed Hunters" }), ["KF2_SERVER_NAME"]);
  assert.ok(!/does not show/.test(ok.notes.join(" ")));
});
test("kf2: a blank admin password is refused, bad characters rejected, nothing rebuilt", async () => {
