import { test } from "node:test";
import assert from "node:assert/strict";
import { cs16Applier } from "../worker/game-config-appliers/cs16";
import { CS16_ADMIN_MARK, CS16_SERVER_CFG, CS16_SPEC, CS16_USERS_INI, patchAmxxAdmin, readAmxxAdmin } from "../lib/game-applier-specs/cs16";
import { readCfgValue } from "../lib/game-applier-specs/source-common";
import { applySourceSetup } from "../lib/game-applier-specs/source-setup";
import { GAME_CONFIG_SCHEMAS } from "../lib/game-config";
import { defaultsFor, envOf, runFam, srcGuest } from "./_cfg-source-helpers";

// shapes taken from the image's own Dockerfile (archont94/counter-strike1.6)
const CFG = `hostname "Counter-Strike 1.6 DockerServer"\nsv_lan 0\n// enable fast download\nsv_downloadurl "http://127.0.0.1/cstrike/"\nsv_allowdownload 1\n`;
const USERS = `; Users file\n"STEAM_0:0:123456" "" "abcdefghijklmnopqrstu" "ce" ; Server admin added during container build\n`;
const guest = (files: Record<string, string> = { [CS16_SERVER_CFG]: CFG, [CS16_USERS_INI]: USERS }, o: Record<string, unknown> = {}) =>
  srcGuest({ container: "cs16", image: "archont94/counter-strike1.6:latest", env: ["PORT=27015", "MAP=de_dust2", "MAXPLAYERS=16", "SV_LAN=0"], binds: ["/opt/cs16:/hlds"], files, ...o });
const V = (over: Record<string, string | number | boolean> = {}) => ({ ...defaultsFor("cs16"), ...over });

test("cs16: every schema field is mapped", () => {
  assert.deepEqual(GAME_CONFIG_SCHEMAS.cs16.fields.map((f) => f.key).filter((k) => !(k in CS16_SPEC.fields)), []);
});
test("cs16: map / max players / LAN go to the container env (LAN as 0/1) and sv_lan in server.cfg", async () => {
  const g = guest();
  const out = await runFam(cs16Applier, g, V({ map: "de_nuke", maxPlayers: 24, lanMode: true }), ["map", "maxPlayers", "lanMode"]);
  assert.equal(out.ok, true, out.notes.join("|"));
  const e = envOf(g, "cs16");
  assert.equal(e.get("MAP"), "de_nuke");
  assert.equal(e.get("MAXPLAYERS"), "24");
  assert.equal(e.get("SV_LAN"), "1");
  assert.equal(readCfgValue(g.files.get(CS16_SERVER_CFG)!, "sv_lan"), "1");
  assert.ok(g.containers.get("cs16")!.binds.includes("/opt/cs16:/hlds"));
});
test("cs16: LAN with no server.cfg yet still applies the env and does not fail", async () => {
  const g = guest({});
  const out = await runFam(cs16Applier, g, V({ lanMode: true }), ["lanMode"]);
  assert.equal(out.ok, true);
  assert.equal(envOf(g, "cs16").get("SV_LAN"), "1");
});
test("cs16: server name, fast download and rcon go into server.cfg; secrets stay out of notes and command lines", async () => {
  const g = guest();
  const out = await runFam(cs16Applier, g, V({ serverName: "My CS Realm", fastDownloadUrl: "http://203.0.113.9/cstrike/", rconPassword: "rconpw-4" }), ["serverName", "fastDownloadUrl", "rconPassword"]);
  assert.equal(out.ok, true, out.notes.join("|"));
  const cfg = g.files.get(CS16_SERVER_CFG)!;
  assert.equal(readCfgValue(cfg, "hostname"), "My CS Realm");
  assert.equal(readCfgValue(cfg, "sv_downloadurl"), "http://203.0.113.9/cstrike/");
  assert.equal(readCfgValue(cfg, "rcon_password"), "rconpw-4");
  assert.ok(cfg.includes("sv_allowdownload 1") && cfg.includes("// enable fast download"));
  assert.equal(g.st.created, 0, "file-only change never rebuilds");
  assert.ok(!JSON.stringify(out).includes("rconpw-4"));
  assert.ok(!g.log.some((l) => l.includes("rconpw-4") && !l.startsWith("write ")));
});
test("cs16: admin SteamID replaces the build-time placeholder admin in users.ini; blank removes ours", async () => {
  const g = guest();
  const out = await runFam(cs16Applier, g, V({ adminSteamId: "STEAM_0:1:4242" }), ["adminSteamId"]);
  assert.equal(out.ok, true, out.notes.join("|"));
  const ini = g.files.get(CS16_USERS_INI)!;
  assert.equal(readAmxxAdmin(ini), "STEAM_0:1:4242");
  assert.ok(!ini.includes("STEAM_0:0:123456"));
  assert.ok(ini.includes("; Users file"));
  const out2 = await runFam(cs16Applier, g, V({ adminSteamId: "" }), ["adminSteamId"]);
  assert.equal(out2.ok, true);
  assert.ok(!g.files.get(CS16_USERS_INI)!.includes(CS16_ADMIN_MARK));
  assert.equal(patchAmxxAdmin("", "STEAM_0:1:1").includes('"abcdefghijklmnopqrstu" "ce"'), true);
});
test("cs16: bad values are rejected before anything changes", async () => {
  const g = guest();
  for (const bad of [{ adminSteamId: "STEAM_9:9:x" }, { fastDownloadUrl: "ftp://x" }, { serverName: 'a"b' }, { rconPassword: "a b" }, { map: "de dust" }]) {
    const out = await runFam(cs16Applier, g, V(bad), Object.keys(bad));
    assert.equal(out.ok, false, JSON.stringify(bad));
  }
  assert.equal(g.files.get(CS16_SERVER_CFG), CFG);
  assert.equal(g.st.created, 0);
});
test("cs16: missing server.cfg is reported (not faked); no-op; rollback restores files", async () => {
  const g = guest({});
  const out = await runFam(cs16Applier, g, V({ serverName: "X" }), ["serverName"]);
  assert.equal(out.ok, true);
  assert.match(out.notes.join(" "), /hasn't created/);
  const g2 = guest();
  await runFam(cs16Applier, g2, V({ serverName: "Same" }), ["serverName"]);
  const w = g2.log.filter((l) => l.startsWith("write")).length;
  await runFam(cs16Applier, g2, V({ serverName: "Same" }), ["serverName"]);
  assert.equal(g2.log.filter((l) => l.startsWith("write")).length, w);
  const g3 = guest(undefined, { startFailsForNew: true });
  const o3 = await runFam(cs16Applier, g3, V({ serverName: "Y", map: "de_nuke" }), ["serverName", "map"]);
  assert.equal(o3.ok, false);
  assert.equal(g3.files.get(CS16_SERVER_CFG), CFG);
  assert.equal(envOf(g3, "cs16").get("MAP"), "de_dust2");
});
test("cs16: setup bake writes SV_LAN as 0/1 (the generic path would write 'false')", () => {
  const script = "docker run -d --name cs16 -e MAP='de_dust2' -e SV_LAN='0' archont94/counter-strike1.6:latest";
  assert.match(applySourceSetup(script, "cs16", V({ lanMode: true })), /-e SV_LAN='1'/);
  assert.match(applySourceSetup(script.replace("'0'", "'false'"), "cs16", V({ lanMode: false })), /-e SV_LAN='0'/);
});
